#[allow(dead_code)]
mod verify {
    use super::*;

    const _: () = assert!(VaultState::DISCRIMINATOR.len() == 8);
    const _: () = assert!(VaultState::INIT_SPACE == 41);

    fn pin_bump(bumps: &InitializeVaultBumps) -> u8 {
        bumps.vault
