        return Err("ZERO_AMOUNT".to_string());
    }
    if sender_balance < amount {
        return Err("INSUFFICIENT_BALANCE".to_string());
    }
    if sender == recipient {
        return Err("SAME_ACCOUNT".to_string());
    }
    Ok(())
}

