function base64ToUtf8(encoded: string): string {
  const bytes: number[] = [];
  let buffer = 0;
  let bits = 0;
  for (let i = 0; i < encoded.length; i++) {
    const value = B64_ALPHABET.indexOf(encoded[i]);
