// on the following line — you cannot lend out write access you do not have.
pub fn demo() -> (u64, u64) {
    let mut vault = sample_vault();

    let added = top_up_to(&mut vault, 750_000);
    let now = balance_of(&vault);

    (added, now) // expect (250_000, 750_000)
}

