// ════════════════════════════════════════════════════════════════════════

const _: fn(u64, u64) -> Option<u64> = add_lamports;
const _: fn(u64, u64) -> Option<u64> = sub_lamports;
const _: fn(u64, u64, u64) -> Option<(u64, u64)> = transfer_lamports;

// add: the ordinary case, the ceiling, and zero
