    #[msg("Deposit would overflow the vault balance")]
    Overflow,
    #[msg("Withdrawal exceeds the vault balance")]
    InsufficientFunds,
    #[msg("Amount must be greater than zero")]
    ZeroAmount,
    #[msg("Signer is not the vault owner")]
    NotOwner,
